<?php if($advanced):?><section class="panel"><div class="panel-title"><h2>Conversion funnel</h2><span>Unique sessions</span></div><ol class="funnel-list"><?php foreach(['visitors'=>'Visitors','product_viewers'=>'Viewed product','cart_users'=>'Added to cart','checkout_users'=>'Started checkout','ordering_users'=>'Created order']as$key=>$label):?><li><span><?= e($label) ?></span><strong><?= e((int)($f[$key]??0)) ?></strong></li><?php endforeach ?></ol></section>
<section class="panel"><div class="panel-title"><h2>Popular products</h2><span>Product views</span></div><?php if(!$a['popular']):?><div class="empty-inline">Product views will appear here.</div><?php else:?><ol class="rank-list"><?php foreach($a['popular']as$row):?><li><span><?= e($row['name']) ?></span><strong><?= e($row['views']) ?></strong></li><?php endforeach ?></ol><?php endif ?></section>
